    }

    bool private internalReverted;
    bytes4 private internalSelector;

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance");

        // Fund the caller's recorded balance inside c.
        c.addToBalance{value: depositAmount}();

        // Record the balance before the withdraw attempt.
        uint256 beforeBalance = c.getBalance(address(this));
        uint256 beforeContractEther = address(c).balance;

        // Force the subsequent withdraw callback to fail by making it hit an assertion.
        internalReverted = true;
        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSignature("withdrawBalance()")
        );

        uint256 afterBalance = c.getBalance(address(this));
        uint256 afterContractEther = address(c).balance;

        assert(!ok && afterBalance == beforeBalance && afterContractEther == beforeContractEther);
    }

    receive() external payable {
        if (internalReverted) {
            assembly { invalid() }
        }
    }
}

